import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The contract's `from` is 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9
        address from = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(from);
        // Provide two recipients; the second call will fail because `from` does not hold enough tokens
        address[] memory tos = new address[](2);
        tos[0] = address(0x1);
        tos[1] = address(0x2);
        uint[] memory vals = new uint[](2);
        vals[0] = 1; // 1 token = 1e18 wei, will succeed
        vals[1] = 2; // 2 tokens = 2e18 wei, will cause revert in reference (not enough balance)
        // Reference version reverts entirely -> the call returns false
        // Buggy version returns false for the failed call and continues, returning true at end
        // We catch the revert to check the boolean result
        bool ok;
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference version, the whole transaction reverts -> ok is false
        // In the buggy version, it does not revert and returns true -> ok is true
        // So assertion: reference holds when ok == false; bug breaks when ok == false (because bug returns true)
        assertTrue(!ok);
    }
}

